/** Read-only source inventory, never executes imported application modules. */
import ts from 'typescript';
import path from 'node:path';
import {readFile,stat} from 'node:fs/promises';
const root=process.cwd(),seen=new Set<string>(),sha=(b:Uint8Array)=>new Bun.CryptoHasher('sha256').update(b).digest('hex');
const historical:any[]=JSON.parse(await readFile('evaluations/research-qa/m78-continuation4-preparation-source-pins.json','utf8'));
const required=['.superpowers/m78-readonly-recovery-entry.ts','.superpowers/m78-private-readonly-recovery.ps1','.superpowers/m78-readonly-recovery-source-closure.ts','tools/staging/check-m78-continuation4-readonly-recovery.ts','evaluations/research-qa/m78-continuation4-readonly-recovery-independent-review.ts'];
const walk=async(file:string):Promise<void>=>{file=file.replaceAll('\\','/');if(seen.has(file))return;seen.add(file);const bytes=await readFile(file);if(!/\.[cm]?[jt]sx?$/.test(file))return;const text=bytes.toString('utf8'),info=ts.preProcessFile(text,true,true);
 for(const ref of info.importedFiles){if(!ref.fileName.startsWith('.'))continue;const base=path.resolve(path.dirname(file),ref.fileName);if(!base.startsWith(root+path.sep))throw Error('Source outside workspace');const options=[base,base+'.ts',base+'.tsx',base+'.js',path.join(base,'index.ts')];let resolved:string|null=null;for(const candidate of options){try{if((await stat(candidate)).isFile()){resolved=path.relative(root,candidate);break}}catch{}}if(!resolved)throw Error('Unresolved source '+ref.fileName+' in '+file);await walk(resolved)}
};
for(const pin of historical)await walk(pin.path);for(const file of required)await walk(file);
const pins=await Promise.all([...seen].sort().map(async p=>({path:p,sha256:sha(await readFile(p))})));
console.log(JSON.stringify(pins));

